const event = $json ?? {};
const workflowName = event.workflow?.name ?? "Unknown workflow";
const workflowId = event.workflow?.id ?? "Unknown";
const executionId = event.execution?.id ?? "Unknown";
const failedNode = event.execution?.lastNodeExecuted ?? "Unknown";
const rawError = String(event.execution?.error?.message ?? "No error message available");
const safeError = rawError
  .replace(/(password|passwd|secret|api[_-]?key|access[_-]?token|authorization)\s*[:=]\s*[^\s,;]+/gi, '$1=[REDACTED]')
  .replace(/\bBearer\s+[A-Za-z0-9._~+\/=-]{10,}/gi, 'Bearer [REDACTED]')
  .slice(0, 900);
const executionUrl = event.execution?.url ?? "Not available";
const mode = event.execution?.mode ?? "Unknown";
const telegramText = [
  "🚨 SUPPORT AUTOMATION ERROR",
  "",
  `Workflow: ${workflowName}`,
  `Workflow ID: ${workflowId}`,
  `Execution ID: ${executionId}`,
  `Failed Node: ${failedNode}`,
  `Execution Mode: ${mode}`,
  "",
  `Error: ${safeError}`,
  "",
  `Execution: ${executionUrl}`
].join("\n");
return {json:{
  telegram_chat_id:"1098071517",
  telegram_text:telegramText,
  workflow_name:workflowName,
  execution_id:executionId,
  failed_node:failedNode,
  error_message:safeError
}};
